if (body.attendees) {
  let attendees = [];
  let parts = body.attendees.split('/').map(p => p.trim()).filter(p => p);
  attendees = parts.map(p => {
    let [email, name] = p.split(',').map(x => x.trim());
    return {
      emailAddress: {
        address: email || '',
        name: name || ''
      },
      type: 'required'
    };
  }).filter(a => a.emailAddress.address);
  body.attendees = attendees;
}
return body;

